function item(id, category, step, concepts, lesson, difficulty, stem, optionText, answer, rationale) {
  const options = optionText.map((text, index) => ({ id: String.fromCharCode(65 + index), text }));

  return {
    id,
    status: "approved",
    category,
    step,
    concepts,
    lesson,
    difficulty,
    format: "multiple_choice",
    stem,
    options,
    answer,
    scoringRule: "single_best_answer",
    rationale,
    correctRationale: rationale,
    incorrectRationales: Object.fromEntries(
      options.filter((option) => option.id !== answer).map((option) => [option.id, `Review ${lesson} before selecting ${option.id}; this option does not best address the priority in the stem.`]),
    ),
    misconceptionTags: concepts,
    source: "Prototype seed item; faculty review required before production use.",
    evidenceReference: "Faculty-authored pilot seed for Harrity Nursing CAT prototype.",
  };
}
